#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> init(n), expect(n);
    for (auto &x : init) scanf("%d", &x);
    for (auto &x : expect) scanf("%d", &x);
    // State per node: flips inherited from ancestors, separately for even and odd indices.
    struct Item { int u, parent, flip[2]; };
    vector<Item> st = {{0, -1, {0, 0}}};
    long long ans = 0;
    while (!st.empty()) {
        Item it = st.back();
        st.pop_back();
        int u = it.u, par = u % 2;
        if ((init[u] ^ it.flip[par]) != expect[u]) {  // only an operation here can still fix u
            it.flip[par] ^= 1;
            ans++;
        }
        for (int c : g[u])
            if (c != it.parent) st.push_back({c, u, {it.flip[0], it.flip[1]}});
    }
    printf("%lld\n", ans);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int m = 2 * (n - 1);
        int[] head = new int[n], nxt = new int[m], to = new int[m];
        Arrays.fill(head, -1);
        int ec = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = nextInt(), b = nextInt();
            to[ec] = b; nxt[ec] = head[a]; head[a] = ec++;
            to[ec] = a; nxt[ec] = head[b]; head[b] = ec++;
        }
        int[] init = new int[n], expect = new int[n];
        for (int i = 0; i < n; i++) init[i] = nextInt();
        for (int i = 0; i < n; i++) expect[i] = nextInt();
        // State per node: flips inherited from ancestors, packed as bit0 = even, bit1 = odd.
        int[] stU = new int[n], stP = new int[n], stF = new int[n];
        int sp = 0;
        stU[sp] = 0; stP[sp] = -1; stF[sp] = 0; sp++;
        long ans = 0;
        while (sp > 0) {
            sp--;
            int u = stU[sp], parent = stP[sp], flip = stF[sp], par = u % 2;
            if ((init[u] ^ (flip >> par & 1)) != expect[u]) {  // only an operation here can still fix u
                flip ^= 1 << par;
                ans++;
            }
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int c = to[e];
                if (c == parent) continue;
                stU[sp] = c; stP[sp] = u; stF[sp] = flip; sp++;
            }
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

type item struct{ u, parent, flip int } // flip: bit0 = even indices, bit1 = odd indices

func main() {
	n := readInt()
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := readInt(), readInt()
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	init := make([]int, n)
	expect := make([]int, n)
	for i := range init {
		init[i] = readInt()
	}
	for i := range expect {
		expect[i] = readInt()
	}
	st := []item{{0, -1, 0}}
	ans := 0
	for len(st) > 0 {
		it := st[len(st)-1]
		st = st[:len(st)-1]
		par := it.u % 2
		if init[it.u]^(it.flip>>par&1) != expect[it.u] { // only an operation here can still fix u
			it.flip ^= 1 << par
			ans++
		}
		for _, c := range g[it.u] {
			if c != it.parent {
				st = append(st, item{c, it.u, it.flip})
			}
		}
	}
	fmt.Println(ans)
}
